    { jobTypes: { [jobKey]: checked } },
    'Job type saved.',
  );
};

const handleProjectMove = (projectId, direction) => {
  if (!selected) return;
  const next =
    direction === 'load'
      ? withProjectLoaded(loadedIds, projectId)
      : withProjectUnloaded(loadedIds, projectId);
